INSERT INTO `faq` VALUES (1,'Bagaimana cara mendapatkan akun?','Ajukan permintaan kepada admin pada jam pelayanan dengan identitas petugas dan unit kerja. Akun akan dibuat oleh admin setelah disetujui.',0,'2026-11-13 03:12:42','2026-11-13 03:12:42'),(2,'Saya lupa kata sandi. Apa yang harus dilakukan?','Hubungi admin pada jam kerja agar kata sandi dapat diatur ulang. Jangan membagikan akun kepada petugas lain.',1,'2026-11-13 03:12:42','2026-11-13 03:12:42'),(3,'Di mana saya melihat cara mengarsipkan dokumen?','Langkah kerja ada di halaman Prosedur. Halaman Manfaat menjelaskan kegunaan sistem dalam tugas sehari-hari.',2,'2026-11-13 03:12:42','2026-11-13 03:12:42');
/*!40000 ALTER TABLE `faq` ENABLE KEYS */;
