INSERT INTO `manfaat` VALUES (1,'Dokumen lebih mudah ditemukan','Nomor surat, perihal, dan klasifikasi tercatat rapi sehingga petugas tidak perlu mencari berkas secara manual berulang kali.','folder',0,'2026-11-13 03:12:42','2026-11-13 03:12:42'),(2,'Lokasi penyimpanan jelas','Setiap dokumen dihubungkan ke ruang, rak, dan boks fisik. Saat dibutuhkan, petugas tahu tepat di mana berkas disimpan.','pin',1,'2026-11-13 03:12:42','2026-11-13 03:12:42'),(3,'Peminjaman tetap terkendali','Siapa yang meminjam, kapan harus dikembalikan, dan status dokumen dapat dipantau tanpa catatan lepas.','circulation',2,'2026-11-13 03:12:42','2026-11-13 03:12:42'),(4,'Digitalisasi dan Proteksi Berkas','Salinan pindaian dokumen (PDF / foto) terlampir pada arsip, sehingga fisik yang lapuk atau hilang tidak menghilangkan isi dokumen.','shield',3,'2026-11-13 03:12:42','2026-11-13 03:12:42'),(5,'Pelabelan QR Code Otomatis','Setiap dokumen langsung mendapat stiker label QR yang siap dicetak, sehingga identifikasi dan verifikasi berkas di rak lebih cepat.','qr',4,'2026-11-13 03:12:42','2026-11-13 03:12:42'),(6,'Transparansi dan Jejak Audit','Riwayat peminjaman dan perubahan data tercatat rinci, menjaga akuntabilitas internal tata usaha tetap dapat ditelusuri.','history',5,'2026-11-13 03:12:42','2026-11-13 03:12:42');
/*!40000 ALTER TABLE `manfaat` ENABLE KEYS */;
UNLOCK TABLES;

